create table public.saved_addresses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,label text not null,recipient_name text not null,phone_number text not null,address_line_1 text not null,address_line_2 text,city text not null,postcode text not null,delivery_notes text,is_default boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create unique index saved_addresses_one_default on public.saved_addresses(user_id) where is_default;create index saved_addresses_user_idx on public.saved_addresses(user_id);alter table public.saved_addresses enable row level security;create policy "address owner" on public.saved_addresses for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
create or replace function public.set_address_default() returns trigger language plpgsql as $$begin if new.is_default then update public.saved_addresses set is_default=false where user_id=new.user_id and id<>new.id;end if;return new;end;$$;create trigger saved_address_default before insert or update on public.saved_addresses for each row execute procedure public.set_address_default();
